    {
        TSliders x(5, 5); FillFrom(x, 0);
        TSliders v(1, 2); FillFrom(v, 3);
        int frees = g_frees;
        TSliders& r = (v = x);
        if (&r != &v || !Same(v, x) || v.capacity() != 5 || g_frees != frees + 1) { std::printf("005798c8_TEST FAIL\n"); return 1; }
    }
    // shrink: size() >= xlen -> copied over the prefix, capacity kept
