typedef CPredicate_And<TAnd3, CIsThingAlive> TAnd4;
typedef CPredicate_And<TAnd4, CIsThingAlive> TAnd5;

static CIsThingAlive Leaf(int id, bool alive) { return CIsThingAlive(CScriptThing(id, alive)); }

static TAnd5 Build(int deadId)
{
    return TAnd5(TAnd4(TAnd3(TAnd2(Leaf(1, deadId != 1), Leaf(2, deadId != 2)), Leaf(3, deadId != 3)), Leaf(4, deadId != 4)), Leaf(5, deadId != 5));
}

int main()
{
    const int n = 5;
    // destruction order: the outermost right term first, the innermost left term last (ids n .. 1)
    {
        TAnd5 p = Build(0);
        g_count = 0;
    }
    if (g_count != n) { std::printf("00ef6de0_TEST FAIL\n"); return 1; }
    for (int i = 0; i < n; ++i)
        if (g_order[i] != n - i) { std::printf("00ef6de0_TEST FAIL\n"); return 1; }
    // the virtual destructor through the base pointer runs the same chain
    {
        TAnd5 p = Build(0);
        CPredicateBase* clone = p.Clone();
        g_count = 0;
        delete clone;
        if (g_count != n || g_order[0] != n || g_order[n - 1] != 1) { std::printf("00ef6de0_TEST FAIL\n"); return 1; }
        g_count = 0;
    }
    // the predicate itself: true only when every term is alive
    for (int dead = 0; dead <= n; ++dead) {
        TAnd5 p = Build(dead);
        bool expect = (dead == 0);
        if (p() != expect) { std::printf("00ef6de0_TEST FAIL\n"); return 1; }
    }
    std::printf("00ef6de0_TEST PASS\n");
    return 0;
}
